def doc(pr,title,paras,signer=SIGN,warning=None):
 d=Document();s=d.sections[0];s.page_width=Cm(21);s.page_height=Cm(29.7);s.top_margin=Cm(2);s.bottom_margin=Cm(2);s.left_margin=Cm(2.3);s.right_margin=Cm(2.3)
